package com.instaclone.controller;
import com.instaclone.model.*; import com.instaclone.repository.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.nio.file.*; import java.util.*;
@Controller public class HomeController { final UserRepository users; final PostRepository posts; final Path uploads=Paths.get("uploads"); HomeController(UserRepository u,PostRepository p){users=u;posts=p;try{Files.createDirectories(uploads);}catch(Exception ignored){}} @GetMapping({"/","/home"}) String home(@RequestParam(defaultValue="")String user,Model m){m.addAttribute("currentUser",users.findByUsername(user).orElse(null));m.addAttribute("posts",posts.findAllByOrderByIdDesc());return "home";} @PostMapping("/post") String post(@RequestParam String username,@RequestParam String caption,@RequestParam(required=false)MultipartFile file)throws Exception{User u=users.findByUsername(username).orElseThrow();Post p=new Post();p.setUser(u);p.setCaption(caption);p.setImageUrl(save(file));posts.save(p);return "redirect:/home?user="+username;} @GetMapping("/explore") String explore(@RequestParam(defaultValue="")String q,Model m){String query=q.trim();m.addAttribute("q",query);m.addAttribute("results",users.findTop10ByUsernameContainingIgnoreCase(query));m.addAttribute("posts",query.isBlank()?posts.findAllByOrderByIdDesc():posts.findByCaptionContainingIgnoreCaseOrUser_UsernameContainingIgnoreCaseOrderByIdDesc(query,query));return "explore";} @GetMapping("/reels") String reels(Model m){m.addAttribute("posts",posts.findAllByOrderByIdDesc());return "reels";} String save(MultipartFile f)throws Exception{if(f==null||f.isEmpty())return "https://picsum.photos/700/700";String n=UUID.randomUUID()+"_"+f.getOriginalFilename().replaceAll("[^a-zA-Z0-9._-]","_");Files.copy(f.getInputStream(),uploads.resolve(n),StandardCopyOption.REPLACE_EXISTING);return "/uploads/"+n;} }
